import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next(), m = (int) next();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = next();
        // The intersection of all filters is [max lower, min upper].
        long left = Long.MIN_VALUE, right = Long.MAX_VALUE;
        for (int i = 0; i < m; i++) {
            left = Math.max(left, next());
            right = Math.min(right, next());
        }
        long count = 0;
        for (long f : a) if (left <= f && f <= right) count++;
        System.out.println(count);
    }
