import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m := int(next()), int(next())
	a := make([]int64, n)
	for i := range a {
		a[i] = next()
	}
	// The intersection of all filters is [max lower, min upper].
	left, right := int64(math.MinInt64), int64(math.MaxInt64)
	for i := 0; i < m; i++ {
		left = max(left, next())
		right = min(right, next())
	}
	count := 0
	for _, f := range a {
